insert into rubric_criteria (role, position, name, strong, weak, weight, source) values
  ('PM', 1, 'Hands-on operations time', 'Has personally done ground-level operations work in freight, logistics, supply chain, ports, warehousing or a similar physical-operations business (handled shipments, documents, carriers, customs, dispatch, exceptions) for at least a year, and the CV names concrete volumes or situations (e.g. "managed 400+ movements monthly", "resolved customs holds"). Operations work in another physical domain (manufacturing floor, field ops, healthcare ops) scores 3-4.', 'Has only worked on software for operations users from a desk - talks about "users", "stakeholders" or "integrations with 3PLs" but has never done the operational job; or no operations exposure at all.', 30, 'Rohan Desai (CHA documentation, JNPT), Sunita Krishnamurthy, Aditya Shetty (JNPT terminal), Meghna Tiwari, Lavanya Iyer (Mahindra Logistics). Absent in Vikram Nair, Rahul Bose, Preetham Rao.'),
  ('PM', 2, 'Unprompted fix that others adopted', 'At least one specific case where they spotted a broken or missing process that was not their assigned work, built a fix themselves quickly (days or weeks - a sheet, tool, checklist, prototype, process), and other people kept using it - the CV says who adopted it and how many (e.g. "adopted by the 12-member team within two weeks", "became the branch''s standard").', 'Only lists features or projects that were their assigned job, or improvements with no sign anyone else adopted them; generic lines like "drove process improvements" or "streamlined workflows" with no trigger, no artefact and no adopters.', 25, 'Rohan Desai (Excel tracker; weekend B/L prototype), Sunita Krishnamurthy (weekend workflow redesign), Meghna Tiwari (onboarding checklist), Lavanya Iyer (visibility dashboard).'),
  ('PM', 3, 'Kills and post-mortems', 'The CV names something that did not work - a feature they killed, a deal they lost, an outage, a failed launch, a wrong assumption - and states what they concluded and what changed afterwards (redirected capacity, new practice, rewritten process). Bonus if they wrote the post-mortem themselves.', 'Every bullet is a success. No killed work, no loss, no reversal, no lesson. "Shipped N features" with no mention of what was dropped.', 20, 'Aditya Shetty (lost-deal post-mortem became standard), Lavanya Iyer (killed 2 features on data; outage post-mortem), Meghna Tiwari (product limitation through 6-week fix). Absent in Vikram Nair, Rahul Bose, Preetham Rao.'),
  ('PM', 4, 'No layer between them and the consequence', 'Worked directly with the people affected by their decisions and owned the outcome without a manager or intermediary layer in between - e.g. "sole PM", "no account manager layer between client and execution", "translated field requirements without a product layer", "no escalation to management in 14 months". For PM, one clear instance is enough for a 5.', 'Always one of several people in a team with a senior person above making the call ("supported senior PMs", "part of a 12-engineer team", "presented roadmap to CTO for approval"); customer contact only through other teams.', 15, 'Lavanya Iyer ("sole PM"; "made calls we trusted immediately"), Aditya Shetty ("no account manager layer"), Rohan Desai ("without a product layer"), Meghna Tiwari. Contrast: Vikram Nair (one of a 4-PM team, roadmap to CTO), Preetham Rao (one of 12 engineers).'),
  ('PM', 5, 'Proof by usage, not credentials', 'Results are stated as what other people did differently - adoption, active use, fewer tickets, retention, on-time shipments - with numbers (e.g. "3x weekly active use within 30 days", "support tickets down 60%"). Certifications and titles are incidental.', 'The CV leans on credentials, frameworks, talks, certifications, or output counts ("shipped 12 features", "Product School CPO", "speaker at...") with little evidence of how users'' behaviour changed.', 10, 'Lavanya Iyer and Meghna Tiwari (usage/churn outcomes) vs Vikram Nair (certifications, speaking, feature counts).'),
  ('SPM', 1, 'Hands-on operations time', 'Two or more years doing ground-level operations work in freight, logistics, supply chain or ports themselves (shipments, documentation, carriers, customs, exceptions), AND has since carried that knowledge into product or systems decisions - the CV links an operational problem they lived to something they later built or decided. Operations in another physical domain scores 3.', 'Domain knowledge only through customers, research or integrations; or operations time that is short (a rotation or internship) and never connected to later product work.', 20, 'Rohan Desai (ops at JNPT -> built the B/L module he once did by hand), Lavanya Iyer (3PL carrier ops -> carrier integration product).'),
  ('SPM', 2, 'Unprompted fix that others adopted', 'Multiple cases (at least two) of spotting a broken process outside their remit, building the fix themselves, and seeing it adopted beyond their own team - other teams, branches, or the whole company - with the adopter count stated. At least one should be a standard or system others now run on.', 'One small team-internal improvement, or improvements described without a trigger, artefact or adopters; or only assigned roadmap work.', 20, 'Rohan Desai (tracker adopted by 12; prototype to 30 users, now a core feature), Lavanya Iyer (dashboard adopted by 2 other regional teams; first carrier review process at the branch).'),
  ('SPM', 3, 'Kills and post-mortems', 'Names a significant call that went wrong or was reversed (killed product line, lost major deal, outage, failed migration), shows they owned the write-up, and states a lasting change that resulted (new standard, changed strategy, practice adopted by others).', 'No failures or reversals at all; or failures mentioned only as someone else''s problem they cleaned up, with no conclusion drawn.', 20, 'Aditya Shetty (post-mortem became team practice), Lavanya Iyer (kills + outage post-mortem with follow-ups to closure).'),
  ('SPM', 4, 'No layer between them and the consequence', 'Sustained periods (a year or more, ideally more than once) as the final decision-maker for an area with no senior person above approving their calls - sole PM, founder or founding team, solo consultant, first hire in a function - including decisions with long-lived consequences (vendor/platform choices, migrations, what not to build), and they lived with the result.', 'Senior titles but decisions routed through a Head/VP/committee; "aligned stakeholders" or "presented to leadership" as the main verbs; ownership only of execution, not of the call.', 30, 'Sunita Krishnamurthy (independent consultant, scoped and ran a full system migration), Rohan Desai (led vendor migration; most senior engineer in the room), Lavanya Iyer (sole PM). Contrast: Vikram Nair.'),
  ('SPM', 5, 'Proof by usage, not credentials', 'Outcomes stated as changes in other people''s behaviour or business results that trace to their decisions - adoption, retention, churn, integration time, unblocked deals - with numbers, across more than one role.', 'Leans on credentials, frameworks, titles, team size or output counts; outcomes vague ("drove growth", "improved efficiency").', 10, 'Meghna Tiwari (6% churn vs 24% team), Lavanya Iyer (3x weekly active use). Contrast: Vikram Nair.');
